async function placeOrder(order) {
  const comp: Array<() => Promise<void>> = [];
  try {
    await activities.authorisePayment(order);  comp.push(() => activities.voidPayment(order));
    await activities.reserveStock(order);      comp.push(() => activities.releaseStock(order));
    await activities.createShipment(order);
  } catch (err) {
    for (const undo of comp.reverse()) await undo();   // run compensations in reverse
    throw err;
  }
}
